with metrics as (select *, lead(age) over w_running as next_age, lag(age) over w_running as prev_age, lead(credit_limit) over w_running as next_credit_limit, lag(credit_limit) over w_running as prev_credit_limit, row_number() over w_running as event_seq from customers window w_running as (partition by country order by credit_limit, id)) select date_trunc('quarter', signup_date) as quarter_start, date_trunc('month', signup_date) as activity_month, count(*) filter (where country = 'TH') as th_rows, percentile_approx(event_seq, 0.95) as event_seq_p95, sort_array(collect_set(country)) as country_list, corr(credit_limit, age) as corr_credit_limit_age, corr(credit_limit, age) as corr_credit_limit_age_2 from metrics group by cube (date_trunc('quarter', signup_date), date_trunc('month', signup_date)) having corr_credit_limit_age >= 0;
